   480→        console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);
   481→
   482→        // 座位映射：1=南, 2=西, 3=北, 4=东（用户视角：自己坐南）
   483→        // 逆时针方向：南(1) -> 西(2) -> 北(3) -> 东(4) -> 南(1)
   484→        const seatToDirection = { 1: '南', 2: '西', 3: '北', 4: '东' };
   485→        const directionOrder = [1, 2, 3, 4]; // 逆时针顺序：南→西→北→东
   486→
   487→        // 第1次掷骰者的座位
   488→        const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;
   489→
   490→        // 第1次骰子点数决定第2次掷骰者：从庄家（第1次掷骰者）开始逆时针数 firstSum 个玩家
   491→        const firstRollerIdx = directionOrder.indexOf(firstRollerSeat);
   492→        const secondRollerIdx = (firstRollerIdx + firstSum - 1) % 4;
   493→        const secondRollerSeat = directionOrder[secondRollerIdx];
   494→
   495→        console.log(`第1次掷骰者: ${seatToDirection[firstRollerSeat]}(座位${firstRollerSeat}), 数${firstSum}个后是: ${seatToDirection[secondRollerSeat]}(座位${secondRollerSeat})`);
   496→
   497→        // 第2次掷骰者面前牌墙的起始位置开始数 total 墩
   498→        // 牌墙序号方向（从玩家视角看自己的牌墙都是左1右17）：
   499→        // - 南(1)：左1，右17
   500→        // - 西(2)：上1，下17
   501→        // - 北(3)：左17，右1
   502→        // - 东(4)：上17，下1
   503→        // 抓牌方向：所有方位都从序号1往17方向数
   504→
   505→        const startPileNum = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 各方位起始序号都是1
   506→        const pileStep = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 序号都递增
   507→
   508→        // 从第2次掷骰者面前开始数 total 墩
   509→        let remainingPiles = total;
   510→        let currentDirIdx = secondRollerIdx;
   511→        let stopPileNum = startPileNum[secondRollerSeat]; // 停在哪一墩的序号
   512→
   513→        while (remainingPiles > 0) {
   514→            const currentDir = directionOrder[currentDirIdx];
   515→            const available = 17; // 每个方位17墩
   516→
   517→            if (remainingPiles > available) {
   518→                remainingPiles -= available;
   519→                currentDirIdx = (currentDirIdx + 1) % 4;
   520→            } else {
   521→                // 计算停在哪个序号
   522→                const start = startPileNum[currentDir];
   523→                const step = pileStep[currentDir];
   524→                stopPileNum = start + (remainingPiles - 1) * step;
   525→                remainingPiles = 0;
   526→            }
   527→        }
   528→
   529→        const stopDirection = directionOrder[currentDirIdx];
   530→        console.log(`数${total}墩后停在: ${seatToDirection[stopDirection]}方第${stopPileNum}墩`);
   531→
   532→        // 抓牌从停的那墩的下一墩开始（逆时针方向）
   533→        // 计算抓牌起始位置
   534→        let drawDirection, drawPile;
   535→        const stopStep = pileStep[stopDirection];
   536→
   537→        if (stopPileNum === (stopStep === 1 ? 17 : 1)) {
   538→            // 停在方位的最后一墩，下一墩是下一个方位的第一墩
   539→            const nextDirIdx = (currentDirIdx + 1) % 4;
   540→            drawDirection = directionOrder[nextDirIdx];
   541→            drawPile = startPileNum[drawDirection];
   542→        } else {
   543→            drawDirection = stopDirection;
   544→            drawPile = stopPileNum + stopStep;
   545→        }
   546→
   547→        console.log(`抓牌起始: ${seatToDirection[drawDirection]}方第${drawPile}墩`);
   548→
   549→        // 确定亮牌位置
   550→        // 抓牌方位的逆时针下一个方位，从序号1开始数 firstSum 墩
   551→        const drawDirIdx = directionOrder.indexOf(drawDirection);
   552→        const shownDirIdx = (drawDirIdx + 1) % 4; // 逆时针下一个
   553→        const shownDirection = directionOrder[shownDirIdx];
   554→
   555→        // 从序号1开始数 firstSum 墩
   556→        const shownStart = startPileNum[shownDirection];
   557→        const shownStep = pileStep[shownDirection];
   558→        const shownPile = shownStart + (firstSum - 1) * shownStep;
   559→
   560→        console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从序号${shownStart}开始数${firstSum}墩）`);
   561→
   562→        // 计算牌堆中的实际索引
   563→        // 牌墙按 [南17墩][西17墩][北17墩][东17墩] 排列（逆时针）
   564→        const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
   565→        // 序号转索引：所有方位序号1对应索引0，序号17对应索引16
   566→        let shownPileIndex = directionToOffset[shownDirection] + (shownPile - 1);
   567→
   568→        // 每墩2张牌，取上面那张（索引*2）
   569→        const shownCardIndex = shownPileIndex * 2;
   570→
   571→        // 获取亮牌
   572→        let shownCard = null;
   573→        if (shownCardIndex >= 0 && shownCardIndex < this.gameState.deck.length) {
   574→            shownCard = this.gameState.deck[shownCardIndex];
   575→            console.log(`亮牌索引: ${shownCardIndex}, 亮牌: ${cardName(shownCard)}`);
   576→
   577→            // 从牌堆中移除亮牌（玩家不可获取）
   578→            this.gameState.shownCard = shownCard;
   579→            this.gameState.deck.splice(shownCardIndex, 1);
   580→            console.log(`亮牌已移除，剩余牌数: ${this.gameState.deck.length}`);
   581→
   582→            // 根据亮牌确定癞子
   583→            const wildCardInfo = this.getWildCardFromShown(shownCard);
   584→            if (wildCardInfo) {
   585→                // 在牌堆中找到对应的癞子牌
   586→                this.gameState.wildCard = this.gameState.deck.find(c =>
   587→                    c.suit === wildCardInfo.suit && c.rank === wildCardInfo.rank
   588→                ) || wildCardInfo; // 如果找不到，使用信息对象
   589→                console.log(`癞子: ${cardName(this.gameState.wildCard)} (根据亮牌${cardName(shownCard)}确定)`);
   590→            }
   591→        } else {
   592→            // 备用：随机选择
   593→            const wildIndex = total % this.gameState.deck.length;
   594→            this.gameState.wildCard = this.gameState.deck[wildIndex];
   595→            console.log(`亮牌索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
   596→        }
   597→
   598→        // 保存抓牌信息用于发牌
   599→        this.gameState.drawInfo = {
   600→            startDirection: secondRollerSeat, // 从第2次掷骰者开始
   601→            drawDirection,
   602→            drawPile,
   603→            totalPiles: total,
   604→            shownCard,
   605→            shownDirection,
   606→            shownPile
   607→        };
   608→    }
   609→
   610→    // 广播骰子状态
   611→    broadcastDiceState() {
   612→        const message = JSON.stringify({
   613→            type: 'diceState',
   614→            data: {
   615→                firstRoll: this.diceState.firstRoll,
   616→                secondRoll: this.diceState.secondRoll,
   617→                currentRoller: this.diceState.currentRoller,
   618→                rollPhase: this.diceState.rollPhase,
   619→                roundPhase: this.gameState.roundPhase,
   620→                shownCard: this.gameState.shownCard || null,
   621→                wildCard: this.gameState.wildCard || null,
   622→                drawInfo: this.gameState.drawInfo || null
   623→            }
   624→        });
   625→
   626→        console.log(`广播骰子状态: rollPhase=${this.diceState.rollPhase}, currentRoller=${this.diceState.currentRoller}`);
   627→
   628→        for (const player of this.players.values()) {
   629→            if (player.ws && player.ws.readyState === WebSocket.OPEN) {
   630→                player.ws.send(message);
   631→            }
   632→        }
   633→    }
   634→
   635→    // 开始发牌
   636→    startDealCards() {
   637→        this.currentRound++;
   638→        this.gameState.roundPhase = 'playing';
   639→        this.roundReadyPlayers.clear();
   640→
   641→        // 重置玩家准备状态（局间准备用）
   642→        for (const player of this.players.values()) {
   643→            player.ready = false;
   644→        }
   645→
   646→        // 重置每局游戏状态
   647→        this.gameState.discardedPile = [];
   648→        this.gameState.showedCards = {};
   649→        this.gameState.faUsed = {};
   650→        this.gameState.lastDrawn = null;
   651→
   652→        // 初始化手牌
   653→        const playerIds = this.getSortedPlayerIds();
   654→        for (const pid of playerIds) {
   655→            this.gameState.hands[pid] = [];
   656→            this.gameState.showedCards[pid] = { fa: [], gang: [] };
   657→            this.gameState.faUsed[pid] = false;
   658→        }
   659→
   660→        // 根据 drawInfo 计算抓牌起始位置
   661→        const drawInfo = this.gameState.drawInfo;
   662→        if (drawInfo && drawInfo.drawDirection) {
   663→            // 方位到数组偏移的映射（牌墙按 东17墩 北17墩 西17墩 南17墩 排列）
   664→            const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 };
   665→            // 每墩2张牌，计算起始索引（从drawDirection方位的第drawPile墩后开始）
   666→            // drawPile 表示"第几墩后开始"，所以实际起始是第 drawPile+1 墩
   667→            let startIndex = (directionToOffset[drawInfo.drawDirection] + drawInfo.drawPile) * 2;
   668→            // 确保索引在有效范围内
   669→            startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));
   670→
   671→            // 重排牌堆，使抓牌位置成为新的牌顶
   672→            if (startIndex > 0) {
   673→                const before = this.gameState.deck.slice(0, startIndex);
   674→                const after = this.gameState.deck.slice(startIndex);
   675→                this.gameState.deck = [...after, ...before];
   676→                console.log(`牌堆重排：从${drawInfo.drawDirection}方第${drawInfo.drawPile}墩后（索引${startIndex}）开始，剩余${this.gameState.deck.length}张`);
   677→            }
   678→        }
