    // 座位映射：1=南, 2=西, 3=北, 4=东（用户视角：自己坐南）
    // 逆时针方向：南(1) -> 西(2) -> 北(3) -> 东(4) -> 南(1)
    const seatToDirection = { 1: '南', 2: '西', 3: '北', 4: '东' };
    const directionOrder = [1, 2, 3, 4]; // 逆时针顺序：南→西→北→东

    // 第1次掷骰者的座位
    const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;

    // 第1次骰子点数决定第2次掷骰者：从庄家（第1次掷骰者）开始逆时针数 firstSum 个玩家
    const firstRollerIdx = directionOrder.indexOf(firstRollerSeat);
    const secondRollerIdx = (firstRollerIdx + firstSum - 1) % 4;
    const secondRollerSeat = directionOrder[secondRollerIdx];

    console.log(`第1次掷骰者: ${seatToDirection[firstRollerSeat]}(座位${firstRollerSeat}), 数${firstSum}个后是: ${seatToDirection[secondRollerSeat]}(座位${secondRollerSeat})`);

    // 第2次掷骰者面前牌墙的起始位置开始数 total 墩
    // 牌墙序号方向（从玩家视角看自己的牌墙都是左1右17）：
    // - 南(1)：左1，右17
    // - 西(2)：上1，下17
    // - 北(3)：左17，右1
    // - 东(4)：上17，下1
    // 抓牌方向：所有方位都从序号1往17方向数

    const startPileNum = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 各方位起始序号都是1
    const pileStep = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 序号都递增

    // 从第2次掷骰者面前开始数 total 墩
    let remainingPiles = total;
    let currentDirIdx = secondRollerIdx;
    let stopPileNum = startPileNum[secondRollerSeat]; // 停在哪一墩的序号

    while (remainingPiles > 0) {
        const currentDir = directionOrder[currentDirIdx];
        const available = 17; // 每个方位17墩

        if (remainingPiles > available) {
            remainingPiles -= available;
            currentDirIdx = (currentDirIdx + 1) % 4;
        } else {
            // 计算停在哪个序号
            const start = startPileNum[currentDir];
            const step = pileStep[currentDir];
            stopPileNum = start + (remainingPiles - 1) * step;
            remainingPiles = 0;
        }
    }

    const stopDirection = directionOrder[currentDirIdx];
    console.log(`数${total}墩后停在: ${seatToDirection[stopDirection]}方第${stopPileNum}墩`);

    // 抓牌从停的那墩的下一墩开始（逆时针方向）
    // 计算抓牌起始位置
    let drawDirection, drawPile;
    const stopStep = pileStep[stopDirection];

    if (stopPileNum === (stopStep === 1 ? 17 : 1)) {
        // 停在方位的最后一墩，下一墩是下一个方位的第一墩
        const nextDirIdx = (currentDirIdx + 1) % 4;
        drawDirection = directionOrder[nextDirIdx];
        drawPile = startPileNum[drawDirection];
    } else {
        drawDirection = stopDirection;
        drawPile = stopPileNum + stopStep;
    }

    console.log(`抓牌起始: ${seatToDirection[drawDirection]}方第${drawPile}墩`);

    // 确定亮牌位置
    // 抓牌方位的逆时针下一个方位，从序号1开始数 firstSum 墩
    const drawDirIdx = directionOrder.indexOf(drawDirection);
    const shownDirIdx = (drawDirIdx + 1) % 4; // 逆时针下一个
    const shownDirection = directionOrder[shownDirIdx];

    // 从序号1开始数 firstSum 墩
    const shownStart = startPileNum[shownDirection];
    const shownStep = pileStep[shownDirection];
    const shownPile = shownStart + (firstSum - 1) * shownStep;

    console.log(`亮牌位置: ${seatToDirection[shownDirection]}方第${shownPile}墩（从序号${shownStart}开始数${firstSum}墩）`);

    // 计算牌堆中的实际索引
    // 牌墙按 [南17墩][西17墩][北17墩][东17墩] 排列（逆时针）
    const directionToOffset = { 1: 0, 2: 17, 3: 34, 4: 51 };
    // 序号转索引：所有方位序号1对应索引0，序号17对应索引16
    let shownPileIndex = directionToOffset[shownDirection] + (shownPile - 1);

    // 每墩2张牌，取上面那张（索引*2）
    const shownCardIndex = shownPileIndex * 2;

    // 获取亮牌
    let shownCard = null;
    if (shownCardIndex >= 0 && shownCardIndex < this.gameState.deck.length) {
        shownCard = this.gameState.deck[shownCardIndex];
        console.log(`亮牌索引: ${shownCardIndex}, 亮牌: ${cardName(shownCard)}`);

        // 从牌堆中移除亮牌（玩家不可获取）
        this.gameState.shownCard = shownCard;
        this.gameState.deck.splice(shownCardIndex, 1);
        console.log(`亮牌已移除，剩余牌数: ${this.gameState.deck.length}`);

        // 根据亮牌确定癞子
        const wildCardInfo = this.getWildCardFromShown(shownCard);
        if (wildCardInfo) {
            // 在牌堆中找到对应的癞子牌
            this.gameState.wildCard = this.gameState.deck.find(c =>
                c.suit === wildCardInfo.suit && c.rank === wildCardInfo.rank
            ) || wildCardInfo; // 如果找不到，使用信息对象
            console.log(`癞子: ${cardName(this.gameState.wildCard)} (根据亮牌${cardName(shownCard)}确定)`);
        }
    } else {
        // 备用：随机选择
        const wildIndex = total % this.gameState.deck.length;
        this.gameState.wildCard = this.gameState.deck[wildIndex];
        console.log(`亮牌索引超出范围，使用备用计算: ${cardName(this.gameState.wildCard)}`);
    }

    // 保存抓牌信息用于发牌
    this.gameState.drawInfo = {
        startDirection: secondRollerSeat, // 从第2次掷骰者开始
        drawDirection,
        drawPile,
        totalPiles: total,
        shownCard,
        shownDirection,
        shownPile
    };
}

// 广播骰子状态
broadcastDiceState() {
    const message = JSON.stringify({
        type: 'diceState',
        data: {
            firstRoll: this.diceState.firstRoll,
            secondRoll: this.diceState.secondRoll,
            currentRoller: this.diceState.currentRoller,
            rollPhase: this.diceState.rollPhase,
            roundPhase: this.gameState.roundPhase,
            shownCard: this.gameState.shownCard || null,
            wildCard: this.gameState.wildCard || null,
            drawInfo: this.gameState.drawInfo || null
        }
    });

    console.log(`广播骰子状态: rollPhase=${this.diceState.rollPhase}, currentRoller=${this.diceState.currentRoller}`);

    for (const player of this.players.values()) {
        if (player.ws && player.ws.readyState === WebSocket.OPEN) {
            player.ws.send(message);
        }
    }
}

// 开始发牌
startDealCards() {
    this.currentRound++;
    this.gameState.roundPhase = 'playing';
    this.roundReadyPlayers.clear();

    // 重置玩家准备状态（局间准备用）
    for (const player of this.players.values()) {
        player.ready = false;
    }

    // 重置每局游戏状态
    this.gameState.discardedPile = [];
    this.gameState.showedCards = {};
    this.gameState.faUsed = {};
    this.gameState.lastDrawn = null;

    // 初始化手牌
    const playerIds = this.getSortedPlayerIds();
    for (const pid of playerIds) {
        this.gameState.hands[pid] = [];
        this.gameState.showedCards[pid] = { fa: [], gang: [] };
        this.gameState.faUsed[pid] = false;
    }

    // 根据 drawInfo 计算抓牌起始位置
    const drawInfo = this.gameState.drawInfo;
    if (drawInfo && drawInfo.drawDirection) {
        // 方位到数组偏移的映射（牌墙按 东17墩 北17墩 西17墩 南17墩 排列）
        const directionToOffset = { 1: 0, 4: 17, 3: 34, 2: 51 };
        // 每墩2张牌，计算起始索引（从drawDirection方位的第drawPile墩后开始）
        // drawPile 表示"第几墩后开始"，所以实际起始是第 drawPile+1 墩
        let startIndex = (directionToOffset[drawInfo.drawDirection] + drawInfo.drawPile) * 2;
        // 确保索引在有效范围内
        startIndex = Math.max(0, Math.min(startIndex, this.gameState.deck.length - 1));

        // 重排牌堆，使抓牌位置成为新的牌顶
        if (startIndex > 0) {
            const before = this.gameState.deck.slice(0, startIndex);
            const after = this.gameState.deck.slice(startIndex);
            this.gameState.deck = [...after, ...before];
            console.log(`牌堆重排：从${drawInfo.drawDirection}方第${drawInfo.drawPile}墩后（索引${startIndex}）开始，剩余${this.gameState.deck.length}张`);
        }
    }

