const total = firstSum + secondSum;

console.log(`第1次骰子: ${firstSum}, 第2次骰子: ${secondSum}, 总计: ${total}`);

// 座位映射：1=南, 2=西, 3=北, 4=东（用户视角：自己坐南）
// 逆时针方向：南(1) -> 西(2) -> 北(3) -> 东(4) -> 南(1)
const seatToDirection = { 1: '南', 2: '西', 3: '北', 4: '东' };
const directionOrder = [1, 2, 3, 4]; // 逆时针顺序：南→西→北→东

// 第1次掷骰者的座位
const firstRollerSeat = this.players.get(this.diceState.firstRoll.playerId)?.seatNum || 1;

// 第1次骰子点数决定第2次掷骰者：从庄家（第1次掷骰者）开始逆时针数 firstSum 个玩家
const firstRollerIdx = directionOrder.indexOf(firstRollerSeat);
const secondRollerIdx = (firstRollerIdx + firstSum - 1) % 4;
const secondRollerSeat = directionOrder[secondRollerIdx];

console.log(`第1次掷骰者: ${seatToDirection[firstRollerSeat]}(座位${firstRollerSeat}), 数${firstSum}个后是: ${seatToDirection[secondRollerSeat]}(座位${secondRollerSeat})`);

// 第2次掷骰者面前牌墙的起始位置开始数 total 墩
// 牌墙序号方向（从玩家视角看自己的牌墙都是左1右17）：
// - 南(1)：左1，右17
// - 西(2)：上1，下17
// - 北(3)：左17，右1
// - 东(4)：上17，下1
// 抓牌方向：所有方位都从序号1往17方向数

const startPileNum = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 各方位起始序号都是1
const pileStep = { 1: 1, 2: 1, 3: 1, 4: 1 }; // 序号都递增

// 从第2次掷骰者面前开始数 total 墩
let remainingPiles = total;
let currentDirIdx = secondRollerIdx;
let stopPileNum = startPileNum[secondRollerSeat]; // 停在哪一墩的序号

while (remainingPiles > 0) {
    const currentDir = directionOrder[currentDirIdx];
    const available = 17; // 每个方位17墩

    if (remainingPiles > available) {
        remainingPiles -= available;
        currentDirIdx = (currentDirIdx + 1) % 4;
    } else {
        // 计算停在哪个序号
        const start = startPileNum[currentDir];
        const step = pileStep[currentDir];
        stopPileNum = start + (remainingPiles - 1) * step;
        remainingPiles = 0;
    }
}

const stopDirection = directionOrder[currentDirIdx];
console.log(`数${total}墩后停在: ${seatToDirection[stopDirection]}方第${stopPileNum}墩`);

// 抓牌从停的那墩的下一墩开始（逆时针方向）
// 计算抓牌起始位置
let drawDirection, drawPile;
const stopStep = pileStep[stopDirection];

if (stopPileNum === (stopStep === 1 ? 17 : 1)) {
    // 停在方位的最后一墩，下一墩是下一个方位的第一墩
    const nextDirIdx = (currentDirIdx + 1) % 4;
    drawDirection = directionOrder[nextDirIdx];
    drawPile = startPileNum[drawDirection];
} else {
    drawDirection = stopDirection;
    drawPile = stopPileNum + stopStep;
}

console.log(`抓牌起始: ${seatToDirection[drawDirection]}方第${drawPile}墩`);

// 确定亮牌位置
// 抓牌方位的逆时针下一个方位，从序号1开始数 firstSum 墩
