file.content:
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    font-weight: bold;
    color: #333;
    box-shadow: 2px 2px 5px rgba(0,0,0,0.3);
}

.dice.rolling {
    animation: diceRoll 0.5s ease-in-out;
}

@keyframes diceRoll {
    0%, 100% { transform: rotate(0deg); }
    25% { transform: rotate(15deg); }
    75% { transform: rotate(-15deg); }
}

.roll-dice-btn {
    padding: 5px 12px;
    font-size: 12px;
    background: linear-gradient(135deg, #e74c3c, #c0392b);
    color: #fff;
    border: none;
    border-radius: 15px;
    cursor: pointer;
    transition: all 0.3s;
    display: none; /* 默认隐藏，只在轮到玩家掷骰子时显示 */
}

.roll-dice-btn:hover {
    transform: scale(1.05);
    box-shadow: 0 0 10px rgba(231, 76, 60, 0.5);
}

.roll-dice-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ==================== 牌墙样式 ==================== */
.wall-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 700px;
    height: 600px;
    pointer-events: none;
    z-index: 0;
    display: none; /* 默认隐藏 */
}

.wall-section {
    position: absolute;
    display: flex;
}

/* 上方牌墙（北-3号位）- 水平排列，居中 */
.wall-top {
    top: 10px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row;
    gap: 1px;
}

/* 下方牌墙（南-1号位）- 水平排列，居中 */
.wall-bottom {
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%);
    flex-direction: row;
    gap: 1px;
}

/* 左方牌墙（西-4号位）- 垂直排列，居中 */
.wall-left {
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column;
    gap: 1px;
}

/* 右方牌墙（东-2号位）- 垂直排列，居中 */
.wall-right {
    right: 10px;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: column;
    gap: 1px;
}

/* 牌墩容器 - 每墩两张牌叠放 */
.wall-pile {
    position: relative;
}

